import {simulate,baseControl,validateControl} from './physics.mjs';
import {rng} from './statistics.mjs';
const bounds=[[100,700],[12,24],[30,60],[.5,3],[25,60],[.05,.3]];
const names=['injection','pwf','frequency','network','temperature','blend'];
export const dominates=(a,b)=>a.objectives.every((v,i)=>v<=b.objectives[i])&&a.objectives.some((v,i)=>v<b.objectives[i]-1e-9);
function archive(points){const u=new Map(points.filter(p=>p.feasible).map(p=>[p.x.map(x=>x.toFixed(5)).join(','),p]));const a=[...u.values()];return a.filter(p=>!a.some(q=>dominates(q,p)));}
function rankCrowd(points){let rest=[...points],rank=0,out=[];while(rest.length){const front=rest.filter(p=>!rest.some(q=>dominates(q,p)));for(const p of front){p.rank=rank;p.crowd=0;}for(let j=0;j<2;j++){const sorted=[...front].sort((a,b)=>a.objectives[j]-b.objectives[j]);if(sorted.length){sorted[0].crowd=sorted.at(-1).crowd=Infinity;const span=sorted.at(-1).objectives[j]-sorted[0].objectives[j]||1;for(let i=1;i<sorted.length-1;i++)sorted[i].crowd+=(sorted[i+1].objectives[j]-sorted[i-1].objectives[j])/span;}}out.push(...front);rest=rest.filter(p=>!front.includes(p));rank++;}return out.sort((a,b)=>a.rank-b.rank||b.crowd-a.crowd);}
export function optimise(p,opts={}){const {algorithm='NSGA-II',population=24,iterations=15,days=60,seed=42,objective='energy',scheme={}}=opts;if(!['MOPSO','NSGA-II','GA'].includes(algorithm)||population<4||population>80||iterations<1||iterations>80)throw Error('算法或计算规模无效');const random=rng(seed),start=performance.now(),b=bounds.map((x,i)=>opts.bounds?.[i]??x);if(b.some(([lo,hi],i)=>!Number.isFinite(lo)||!Number.isFinite(hi)||lo>hi||lo<bounds[i][0]||hi>bounds[i][1]))throw Error('变量边界超出允许范围');let evaluations=0;
 const evaluate=x=>{evaluations++;const c={...baseControl,...scheme,...Object.fromEntries(names.map((k,i)=>[k,x[i]]))};let result;try{if(validateControl(p,c).length)throw Error('约束');result=simulate(p,c,days);}catch{return {x,control:c,feasible:false,objectives:[1e20,1e20]};}const f=[-result.oil,objective==='water'?result.watercut:result.energy];return {x,control:c,feasible:result.feasible,objectives:f,oil:result.oil,energy:result.energy,npv:result.npv,watercut:result.watercut,specificEnergy:result.specificEnergy,peakPower:result.peakPower};};
 const clamp=(x,i)=>Math.max(b[i][0],Math.min(b[i][1],algorithm==='GA'?Math.round(x/(i===5?.05:i===3?.1:1))*(i===5?.05:i===3?.1:1):x));
 let pop=Array.from({length:population},()=>evaluate(b.map(([lo,hi],i)=>clamp(lo+random()*(hi-lo),i)))),best=pop.map(p=>p),velocity=pop.map(()=>b.map(()=>0)),ar=archive(pop),history=[];
 for(let iteration=0;iteration<iterations;iteration++){
 if(algorithm==='MOPSO'){pop=pop.map((point,n)=>{const leader=ar.length?ar[Math.floor(random()*ar.length)]:best[n];const x=point.x.map((v,i)=>{velocity[n][i]=.65*velocity[n][i]+1.4*random()*(best[n].x[i]-v)+1.4*random()*(leader.x[i]-v);return clamp(v+velocity[n][i]+(random()<.08?(random()-.5)*(b[i][1]-b[i][0])*.2:0),i);});const q=evaluate(x);if(q.feasible&&(!best[n].feasible||dominates(q,best[n])||(!dominates(best[n],q)&&random()<.5)))best[n]=q;return q;});}
 else{const sorted=rankCrowd(pop),tournament=()=>{const a=sorted[Math.floor(random()*sorted.length)],c=sorted[Math.floor(random()*sorted.length)];return a.rank<c.rank||a.rank===c.rank&&a.crowd>=c.crowd?a:c;},children=[];while(children.length<population){const a=tournament(),c=tournament();children.push(evaluate(a.x.map((v,i)=>{const w=random();let q=w*v+(1-w)*c.x[i];if(random()<1/6)q+=(random()-.5)*(b[i][1]-b[i][0])*.3;return clamp(q,i);})));}pop=rankCrowd([...pop,...children]).slice(0,population);}
 ar=archive([...ar,...pop]);if(ar.length>100)ar=rankCrowd(ar).slice(0,100);history.push({iteration:iteration+1,bestOil:ar.length?Math.max(...ar.map(a=>a.oil)):null,bestEnergy:ar.length?Math.min(...ar.map(a=>a.energy)):null,archive:ar.length});}
 return {algorithm,archive:ar,history,evaluations,duration:(performance.now()-start)/1000,days,objective,seed};
}
